@Service
public class TransferService {
    @Transactional(isolation = Isolation.SERIALIZABLE, timeout = 5)
    public void transfer(long from, long to, long cents) {
        accounts.debit(from, cents);   // session enlists; row locks acquired here
        accounts.credit(to, cents);    // no lock or commit calls in business code
    }                                  // commit, or rollback on exception, at the proxy
}
